import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.stream.Stream;

public class DirectorySizeReporterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static long size(Path root) {
        try {
            return DirectorySizeReporter.totalSize(root);
        } catch (Exception e) {
            System.out.println("FAIL  totalSize threw " + e.getClass().getSimpleName());
            failures++;
            return -1L;
        }
    }

    static int count(Path root) {
        try {
            return DirectorySizeReporter.fileCount(root);
        } catch (Exception e) {
            System.out.println("FAIL  fileCount threw " + e.getClass().getSimpleName());
            failures++;
            return -1;
        }
    }

    static void write(Path file, String content) throws IOException {
        Files.write(file, content.getBytes(StandardCharsets.US_ASCII));
    }

    static void deleteTree(Path root) throws IOException {
        if (root == null || !Files.exists(root)) {
            return;
        }
        try (Stream<Path> paths = Files.walk(root)) {
            for (Path p : paths.sorted(Comparator.reverseOrder()).toList()) {
                Files.deleteIfExists(p);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Path tree = null;
        Path empty = null;
        try {
            tree = Files.createTempDirectory("sizereport");
            write(tree.resolve("notes.txt"), "abc");
            Path sub = Files.createDirectory(tree.resolve("sub"));
            write(sub.resolve("data.bin"), "de");
            Path deep = Files.createDirectory(sub.resolve("deep"));
            write(deep.resolve("more.txt"), "0123456789");
            write(deep.resolve("blank.txt"), "");
            Files.createDirectory(tree.resolve("nothing-here"));

            check("total size of the whole tree", 15L, size(tree));
            check("file count of the whole tree", 4, count(tree));
            check("total size of a sub-tree", 12L, size(sub));
            check("file count of a sub-tree", 3, count(sub));
            check("deepest folder size", 10L, size(deep));
            check("empty file still counts", 2, count(deep));

            empty = Files.createTempDirectory("sizereport-empty");
            check("empty directory count", 0, count(empty));

            Path single = tree.resolve("notes.txt");
            check("a single file as the root", 3L, size(single));
        } finally {
            deleteTree(tree);
            deleteTree(empty);
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

